import{z as i,x as d,o as s,c as l,q as E,j as A,D as a,d as t,s as c,S as n,b as r}from"./chunks/framework.C8m1ZpeB.js";const b=JSON.parse('{"title":"套接字缓冲与背压","description":"","frontmatter":{"title":"套接字缓冲与背压","date":"2026-09-08T00:00:00.000Z","section":"cs"},"headers":[],"relativePath":"cs/socket-buffers.md","filePath":"cs/socket-buffers.md","lastUpdated":1791063341000}'),p={name:"cs/socket-buffers.md"};function B(m,e,_,f,u,C){const o=d("Mermaid");return s(),l("div",null,[e[2]||(e[2]=E('<h1 id="套接字缓冲与背压" tabindex="-1">套接字缓冲与背压 <a class="header-anchor" href="#套接字缓冲与背压" aria-label="Permalink to &quot;套接字缓冲与背压&quot;">​</a></h1><div class="epigraph"><p>每个 sock 有接收与发送内存会计：队列里的 sk_buff 计入 rmem/wmem，满了就对应用或对 TCP 窗口施压，而不是在网卡上无限堆。</p><footer>—— 据 POSIX SO_RCVBUF/SO_SNDBUF；Linux 对 sk_buff 会计与 tcp_mem 的说明；Stevens, <em>UNP</em></footer></div><p><a href="/cs/tx-path-qdisc">上一课</a>会在 qdisc 丢包。<a href="/cs/rx-path">RX</a> 会把 skb 挂进 sk。缺口是 <strong>套接字缓冲</strong>：谁付钱、何时 <code>EAGAIN</code>、TCP 窗口如何跟着变。</p><h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2><p>读者慢，内核若无限排队，内存被一个连接吃光。<code>sk_rmem_alloc</code> 超 <code>sk_rcvbuf</code> 则 drop 或缩小窗口。发送：未确认数据占 <code>sk_wmem</code>，满则 <code>send</code> 阻塞或 EAGAIN。缺口：自动调优（tcp_moderate_rcvbuf）；cgroup 的 memory 与 net 会计交叉；UDP 无窗口，只能丢。本课不把每条 sysctl 当考纲。</p><p><span class="marginnote">术语翻译：背压（backpressure）就是下游慢时把压力原路传回上游——水管堵住，泵自然憋住。落到内核是两处计数器：接收缓冲满了缩通告窗口，发送缓冲满了让 <code>send</code> 阻塞或返回 EAGAIN；UDP 没有窗口这条回传通道，只能默默丢包。</span></p><p><span class="marginnote">SO_SNDBUF 是提示，内核常加倍记账。unix 域套接字也有类似缓冲，不经 qdisc。</span></p><h2 id="方法" tabindex="-1">方法 <a class="header-anchor" href="#方法" aria-label="Permalink to &quot;方法&quot;">​</a></h2><p><code>recv</code>：从 sk 队列剥 skb，拷到用户（或 zerocopy），减会计，可能发窗口更新。<code>send</code>：分配 skb，会计加，进 TCP 发送队列，再走 TX。对照 <a href="/cs/page-cache">页缓存</a>：文件脏页有 writeback；套接字没有盘，只有对端 ACK 或本地读。对照 blkio：那是块设备，这里是字节流内存。</p>',9)),(s(),A(n,null,{default:a(()=>[c(o,{id:"mermaid-25",class:"mermaid",graph:"flowchart%20TD%0A%20%20RX%5B%22%E5%85%A5%E5%8C%85%22%5D%20--%3E%20RMEM%5B%22%E8%AE%A1%E5%85%A5%20rcvbuf%22%5D%0A%20%20RMEM%20--%3E%7C%22%E6%BB%A1%22%7C%20BACK%5B%22%E4%B8%A2%E6%88%96%E7%BC%A9%E7%AA%97%E5%8F%A3%22%5D%0A%20%20SND%5B%22send%22%5D%20--%3E%20WMEM%5B%22%E8%AE%A1%E5%85%A5%20sndbuf%22%5D%0A%20%20WMEM%20--%3E%7C%22%E6%BB%A1%22%7C%20BLK%5B%22%E9%98%BB%E5%A1%9E%E6%88%96%20EAGAIN%22%5D%0A"})]),fallback:a(()=>[...e[0]||(e[0]=[t(" Loading... ",-1)])]),_:1})),e[3]||(e[3]=r("h2",{id:"机制",tabindex:"-1"},[t("机制 "),r("a",{class:"header-anchor",href:"#机制","aria-label":'Permalink to "机制"'},"​")],-1)),e[4]||(e[4]=r("p",null,"背压把端到端的「谁更快」收成内核计数器，保护主机。TCP 把接收缓冲翻译成通告窗口，于是慢读者压住快写者——这是传输课在 OS 里的落点。不要写成量化订单流控。",-1)),(s(),A(n,null,{default:a(()=>[c(o,{id:"mermaid-32",class:"mermaid",graph:"flowchart%20LR%0A%20%20A%5B%22%E5%AF%B9%E7%AB%AF%E5%8F%91%E6%95%B0%E6%8D%AE%22%5D%20--%3E%20B%5B%22%E8%BF%9B%E5%85%A5%E6%9C%AC%E7%AB%AF%E6%8E%A5%E6%94%B6%E7%BC%93%E5%86%B2%20%E8%AE%A1%E5%85%A5%20rmem%22%5D%0A%20%20B%20--%3E%20C%7B%22%E5%BA%94%E7%94%A8%20recv%20%E8%85%BE%E5%BE%97%E5%BF%AB%E5%90%97%3F%22%7D%0A%20%20C%20--%20%22%E5%BF%AB%22%20--%3E%20D%5B%22%E7%BC%93%E5%86%B2%E8%85%BE%E7%A9%BA%20%E9%80%9A%E5%91%8A%E7%AA%97%E5%8F%A3%E6%94%BE%E5%A4%A7%22%5D%0A%20%20C%20--%20%22%E6%85%A2%22%20--%3E%20E%5B%22%E7%BC%93%E5%86%B2%E5%A0%86%E7%A7%AF%20%E9%80%9A%E5%91%8A%E7%AA%97%E5%8F%A3%E7%BC%A9%E5%B0%8F%22%5D%0A%20%20E%20--%3E%20F%5B%22%E5%AF%B9%E7%AB%AF%E5%9C%A8%E9%80%94%E6%95%B0%E6%8D%AE%E8%A2%AB%E5%B0%81%E9%A1%B6%20%E5%8F%AA%E8%83%BD%E7%AD%89%22%5D%0A%20%20D%20--%3E%20A%0A%20%20F%20--%3E%20A%0A"})]),fallback:a(()=>[...e[1]||(e[1]=[t(" Loading... ",-1)])]),_:1})),e[5]||(e[5]=E('<p><span class="marginnote">这张图回答「TCP 怎么把本端的内存压力传给对端」：接收缓冲的水位被翻译成通告窗口塞进 ACK，慢读者因此反向掐住快写者——背压不需要任何应用层协议，全靠这一个反馈环。</span></p><p>与 <a href="/cs/napi">NAPI</a>：NAPI 配额是 CPU 时间；rmem 是内存。两者都会 drop，原因不同。</p><p>实现上：tcp_rmem 三元组是自动调优的范围，SO_RCVBUF 会关掉自动。内存压力下 tcp_mem 进入压力档，强制缩小窗口。unix 套接字的缓冲是内核内存，也进 memcg。 读法上只引用<a href="/cs/tx-path-qdisc">上一课</a>的结论，不把对象换成训练推理或限价簿。</p><p><span class="marginnote">数字实例：Linux 的接收缓冲自动调优范围常取 128 KB 到 6 MB（tcp_rmem 三元组），长肥管道会自动往大调。注意一旦显式 <code>setsockopt</code> 设了 SO_RCVBUF，自动调优就被关掉——不少「手动调了反而更慢」的案例都栽在这一行上。</span></p><p>本课在操作系统进阶的「网络栈 / 收发路径」课序里，对象是 <strong>套接字缓冲与背压</strong>。</p><ul><li>先修只引用，不重导：上一课的结论当公理，本课只补差。</li><li>五栏不吞并：不把本课写成大模型训练/推理，也不写成限价簿或权重量化。</li><li>文献用 OSTEP、McKusick、内核文档与具名会议论文；不发明 arXiv 编号。</li></ul><h2 id="边界" tabindex="-1">边界 <a class="header-anchor" href="#边界" aria-label="Permalink to &quot;边界&quot;">​</a></h2><p>本课不引入 <code>tcp_notsent_lowat</code> 的全部应用调优。不保证 RDMA 的 QP 缓冲走同一会计。下一课把 TCP 状态机在内核里的要点钉住，而不重开拥塞控制数学全文。</p><p><span class="marginnote">常见误区：以为 SO_SNDBUF/SO_RCVBUF 越大吞吐越高。大缓冲只吸收突发、不创造带宽，反而拉长排队时延（缓冲膨胀，bufferbloat）；对时延敏感的服务，宁可让缓冲小一点，让背压早点起作用。</span></p><p>版本字段会变，课序钉的是机制对象「套接字缓冲与背压」，不是某一主线内核的结构体名。 后课默认：套接字有内存上限并反向施压。内核 TCP 实现的队列与定时器要点，下一课。</p><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><ul><li>rcv/snd 缓冲会计限制每连接内存。</li><li>满则丢、缩窗口或阻塞应用。</li><li>内核 TCP 要点是下一课。</li><li>出处：Stevens <em>UNP</em>；Linux tcp；POSIX socket 选项。</li></ul>',12))])}const k=i(p,[["render",B]]);export{b as __pageData,k as default};
